import zipfile
import xml.etree.ElementTree as ET

NS = {"m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main"}
path = "budget.xlsx"

with zipfile.ZipFile(path) as z:
    sheet_xml = z.read("xl/worksheets/sheet1.xml")

root = ET.fromstring(sheet_xml)
rows = []
for row in root.findall(".//m:sheetData/m:row", NS):
    row_data = {}
    for c in row.findall("m:c", NS):
        ref = c.get("r")
        t = c.get("t")
        f = c.find("m:f", NS)
        v = c.find("m:v", NS)
        isel = c.find("m:is", NS)
        if f is not None:
            val = f"FORMULA: {f.text}"
        elif v is not None:
            val = v.text
        elif isel is not None:
            texts = [t.text or "" for t in isel.findall(".//m:t", NS)]
            val = "".join(texts)
        else:
            val = None
        if t == "b" and val not in (None,):
            val = val == "1"
        row_data[ref] = val
    rows.append(row_data)

for r in rows:
    print(r)

# Sum expenses C11:C22
expenses = []
for r in rows:
    for ref, val in r.items():
        if ref.startswith("C") and ref[1:].isdigit():
            n = int(ref[1:])
            if 11 <= n <= 22 and val is not None and not str(val).startswith("FORMULA"):
                expenses.append((ref, float(val)))
total = sum(v for _, v in expenses)

# Per-category totals from column A
cats = {}
for r in rows:
    a = r.get("A", None)
    c = r.get("C", None)
    if a and c is not None and not str(c).startswith("FORMULA"):
        n = int([k for k in r if k.startswith("C")][0][1:])
        if 11 <= n <= 22:
            cats[a] = cats.get(a, 0) + float(c)

print("\nExpense rows:", expenses)
print("Category totals:", cats)
print("TOTAL EXPENSES:", total)

import zipfile
import xml.etree.ElementTree as ET

NS = {"m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main"}
path = "budget.xlsx"

with zipfile.ZipFile(path) as z:
    sheet_xml = z.read("xl/worksheets/sheet1.xml")

root = ET.fromstring(sheet_xml)
rows = []
for row in root.findall(".//m:sheetData/m:row", NS):
    row_data = {}
    for c in row.findall("m:c", NS):
        ref = c.get("r")
        t = c.get("t")
        v = c.find("m:v", NS)
        isel = c.find("m:is", NS)
        if v is not None:
            val = v.text
        elif isel is not None:
            texts = [t.text or "" for t in isel.findall(".//m:t", NS)]
            val = "".join(texts)
        else:
            val = None
        if t == "b" and val is not None:
            val = val == "1"
        row_data[ref] = val
    rows.append(row_data)

# Build cell map: (col, row) -> value
cells = {}
for r in rows:
    for ref, val in r.items():
        col = "".join(ch for ch in ref if ch.isalpha())
        rownum = int("".join(ch for ch in ref if ch.isdigit()))
        cells[(col, rownum)] = val

cats = {}
expenses = []
for n in range(11, 23):
    cat = cells.get(("A", n))
    val = cells.get(("C", n))
    if cat and val is not None:
        v = float(val)
        expenses.append((cat, val, v))
        cats[cat] = cats.get(cat, 0) + v

print("Expense rows (category | item | amount):")
for n in range(11, 23):
    item = cells.get(("B", n))
    print(f"  {cells.get(('A', n)):<14} {item:<18} {cells.get(('C', n))}")

print("\nCategory totals:")
for cat, tot in cats.items():
    print(f"  {cat:<14} {tot:,.2f}")

print(f"\nTOTAL EXPENSES: {sum(v for _, _, v in expenses):,.2f}")

